79.     @VisibleForTesting
80.     static final String CK_IPFIX_DEFINITION_PATH = "ipfix_definition_path";
81.     private static final Logger LOG = LoggerFactory.getLogger(IpfixCodec.class);
82. 
83.     @VisibleForTesting
84.     static final String IPFIX_STANDARD_DEFINITION = "/ipfix-iana-elements.json";
85.     private final IpfixAggregator ipfixAggregator;
