88.     private InformationElementDefinitions infoElementDefs;
89. 
90.     @Inject
91.     protected IpfixCodec(@Assisted Configuration configuration, IpfixAggregator ipfixAggregator, MessageFactory messageFactory) throws IOException {
92.         super(configuration);
93.         this.ipfixAggregator = ipfixAggregator;
94.         this.messageFactory = messageFactory;
95.         final URL standardIPFixDefTemplate = Resources.getResource(IpfixCodec.class, IPFIX_STANDARD_DEFINITION);
96.         final List<String> customDefFilePathList = configuration.getList(CK_IPFIX_DEFINITION_PATH);
97.         final List<URL> filePaths = new ArrayList<>();
98.         if (customDefFilePathList == null || customDefFilePathList.isEmpty()) {
99.             infoElementDefs = new InformationElementDefinitions(standardIPFixDefTemplate);
100.         } else {
101.             checkValidFilePath(customDefFilePathList);
102.             filePaths.add(standardIPFixDefTemplate);
103.             for (String filePath : customDefFilePathList) {
104.                 URL customDefURL = url(filePath.trim());
105.                 filePaths.add(customDefURL);
106.             }
107.             URL[] urls = convertToArray(filePaths);
108.             infoElementDefs = new InformationElementDefinitions(urls);
109.         }
110.         this.parser = new IpfixParser(this.infoElementDefs);
111.     }
