118.     URL[] convertToArray(List<URL> urls) {
119.         URL[] urlArray = new URL[urls.size()];
120.         return urls.toArray(urlArray);
121.     }
122. 
123.     void checkValidFilePath(List<String> customDefFilePathList) throws IpfixException {
124.         for (String filePath : customDefFilePathList) {
125.             File file = new File(filePath.trim());
126.             validateFilePath(file);
127.         }
128.     }
