130.     public void validateFilePath(File customDefFile) throws IpfixException {
131.         if (customDefFile.isDirectory()) {
132.             throw new IpfixException("The specified path is a folder. Please specify the full path to the file.");
133.         } else if (!customDefFile.exists()) {
134.             throw new IpfixException("The specified file does not exist.");
135.         }
136.     }
