138.     /**
139.      * Parses out the fields from the flow record, assigns v5 fixed format fields and create message
140.      *
141.      * @param record
142.      * @return
143.      */
144.     private static String toMessageString(Flow record) {
145.         LOG.debug("IPFIX message being assembled from flow record [{}].", record.fields());
146.         final ImmutableMap<String, Object> fields = record.fields();
147.         final long packetCount = (long) fields.getOrDefault("packetDeltaCount", 0L);
148.         long octetCount = (long) fields.getOrDefault("octetDeltaCount", 0L);
149.         if (octetCount == 0L) {
150.             octetCount = (long) fields.getOrDefault("fwd_flow_delta_bytes", 0L);
151.         }
152. 
153.         String srcAddr = (String) fields.get("sourceIPv4Address");
154.         String dstAddr = (String) fields.get("destinationIPv4Address");
155.         if (srcAddr == null) {
156.             srcAddr = (String) fields.get("sourceIPv6Address");
157.         }
158.         if (dstAddr == null) {
159.             dstAddr = (String) fields.get("destinationIPv6Address");
160.         }
161. 
162.         final Number srcPort = (Number) fields.get("sourceTransportPort");
163.         final Number dstPort = (Number) fields.get("destinationTransportPort");
164.         final long protocol = Long.parseLong(String.valueOf(fields.getOrDefault("protocolIdentifier", 0L)));
165. 
166.         // TODO should this be configurable?
167.         return createMessageString(packetCount, octetCount, srcAddr, dstAddr, srcPort, dstPort, protocol);
168.     }
169. 
170.     private static String createMessageString(long packetCount, long octetCount, String srcAddr, String dstAddr,
171.                                               Number srcPort, Number dstPort, long protocol) {
172.         String message = String.format(Locale.ROOT, "Ipfix [" + srcAddr + "]:" + srcPort + " <> [" + dstAddr + "]:" + dstPort + " " +
173.                 "proto:" + protocol + " pkts:" + packetCount + " bytes:" + octetCount);
174.         return message;
175.     }
