189.     public Collection<Message> decodeMessages(@Nonnull RawMessage rawMessage) {
190.         LOG.debug("Attempting to decode raw messages now.");
191.         final ResolvableInetSocketAddress remoteAddress = rawMessage.getRemoteAddress();
192.         final InetSocketAddress sender = remoteAddress != null ? remoteAddress.getInetSocketAddress() : null;
193.         try {
194.             final IpfixJournal.RawIpfix rawIpfix = IpfixJournal.RawIpfix.parseFrom(rawMessage.getPayload());
195.             final Map<Integer, ByteString> templatesMap = rawIpfix.getTemplatesMap();
196. 
197.             final Map<Integer, TemplateRecord> templateRecordMap = Seq.seq(templatesMap)
198.                     .map(entry -> entry.map2(byteString -> parser.parseTemplateRecord(Unpooled.wrappedBuffer(byteString.toByteArray()))))
